'use client';

import Link from 'next/link';
import { ChevronDown, ChevronRight } from 'lucide-react';
import { cn } from '@/app/lib/utils';

interface NavChild {
  label: string;
  href: string;
}

interface NavSectionProps {
  label: string;
  icon: React.ReactNode;
  href?: string;
  children?: NavChild[];
  isExpanded?: boolean;
  onToggle?: () => void;
  isActive?: (href: string) => boolean;
  testIdPrefix?: string;
  onNavigate?: () => void;
  badge?: number;
}

export function NavSection({
  label,
  icon,
  href,
  children,
  isExpanded = false,
  onToggle,
  isActive = () => false,
  testIdPrefix = 'nav',
  onNavigate,
  badge,
}: NavSectionProps) {
  const slugLabel = label.toLowerCase().replace(/\s+/g, '-');

  if (children && children.length > 0) {
    return (
      <div className="mb-1">
        <button
          onClick={onToggle}
          className="w-full flex items-center justify-between px-3 py-2.5 rounded-lg text-gray-300 hover:bg-white/5 transition-colors"
          data-testid={`button-${testIdPrefix}-${slugLabel}`}
        >
          <div className="flex items-center gap-3 overflow-hidden">
            <div className="shrink-0 relative">
              {icon}
              {badge !== undefined && badge > 0 && !isExpanded && (
                <span className="absolute -top-1.5 -right-1.5 bg-red-500 text-white text-[10px] font-bold rounded-full min-w-[16px] h-4 flex items-center justify-center px-1" data-testid="badge-notification-count">
                  {badge > 99 ? '99+' : badge}
                </span>
              )}
            </div>
            <span className="font-medium truncate">{label}</span>
            {badge !== undefined && badge > 0 && isExpanded && (
              <span className="bg-red-500 text-white text-[10px] font-bold rounded-full min-w-[16px] h-4 flex items-center justify-center px-1 shrink-0" data-testid="badge-notification-count">
                {badge > 99 ? '99+' : badge}
              </span>
            )}
          </div>
          {isExpanded ? (
            <ChevronDown className="h-4 w-4" />
          ) : (
            <ChevronRight className="h-4 w-4" />
          )}
        </button>
        {isExpanded && (
          <div className="ml-8 mt-1 space-y-1">
            {children.map((child) => (
              <Link
                key={child.href}
                href={child.href}
                onClick={onNavigate}
                className={cn(
                  "block px-3 py-2 rounded-lg text-sm transition-colors",
                  isActive(child.href)
                    ? "bg-white/10 text-white font-medium"
                    : "text-gray-400 hover:text-white hover:bg-white/5"
                )}
                data-testid={`link-${testIdPrefix}-${child.label.toLowerCase().replace(/\s+/g, '-')}`}
              >
                {child.label}
              </Link>
            ))}
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="mb-1">
      <Link
        href={href!}
        onClick={onNavigate}
        className={cn(
          "flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors overflow-hidden",
          isActive(href!)
            ? "bg-white/10 text-white font-medium"
            : "text-gray-300 hover:bg-white/5"
        )}
        data-testid={`link-${testIdPrefix}-${slugLabel}`}
      >
        <div className="shrink-0">{icon}</div>
        <span className="font-medium truncate">{label}</span>
      </Link>
    </div>
  );
}
